<template><div class="attendance-pwa"><PwaPageHeader icon="fas fa-check-double" title="Persetujuan" subtitle="Kelola pengajuan yang menunggu" /><div class="stats"><button v-for="c in cards" :key="c.key" type="button" :class="c.class" @click="active=c.key"><span>{{c.label}}</span><strong>{{counts[c.key]||0}}</strong></button></div><div class="filter-row"><button v-for="t in tabs" :key="t.key" :class="{active:active===t.key}" @click="active=t.key">{{t.label}} <b>{{counts[t.key]||0}}</b></button></div><div class="card"><div class="title"><div><h6>Pengajuan Menunggu</h6><span>{{filtered.length}} item</span></div><button class="icon-btn" @click="loadData"><i class="fas fa-sync-alt" :class="{'fa-spin':loading}"></i></button></div><div v-if="!filtered.length" class="empty">Tidak ada pengajuan menunggu.</div><div v-else class="list"><div v-for="x in filtered" :key="`${x.type}-${x.id}`" class="item"><div class="top"><div><strong>{{x.pegawai?.nama||'-'}}</strong><small>{{x.type_label||'-'}} · {{x.pegawai?.nip||'-'}}</small></div><span class="status pending">Menunggu</span></div><div class="mini"><span>Tanggal</span><strong>{{formatDate(x.tanggal)}}<template v-if="x.tanggal_selesai"> s.d {{formatDate(x.tanggal_selesai)}}</template></strong></div><div class="mini"><span>Detail</span><strong>{{detail(x)}}</strong></div><div class="mini"><span>Keperluan</span><strong>{{x.keperluan||'-'}}</strong></div><button v-if="x.dokumen_url" type="button" class="attachment" @click="props.openDocument(x)"><i class="fas fa-paperclip"></i> Lampiran</button><div class="actions"><button type="button" @click="process(x,'approved')">Setujui</button><button type="button" @click="process(x,'rejected')">Tolak</button></div></div></div></div></div>

</template>
<script setup>import {computed,ref} from 'vue';import PwaPageHeader from '../../../components/PwaPageHeader.vue';const props=defineProps({loading:Boolean,items:{type:Array,default:()=>[]},counts:{type:Object,default:()=>({all:0,'cuti-izin':0,koreksi:0,lembur:0})},formatDate:{type:Function,required:true},loadData:{type:Function,required:true},process:{type:Function,required:true},openDocument:{type:Function,required:true}});const active=ref('all');const tabs=[{key:'all',label:'Semua'},{key:'cuti-izin',label:'Cuti/Izin'},{key:'koreksi',label:'Koreksi'},{key:'lembur',label:'Lembur'}];const cards=[{key:'all',label:'Menunggu',class:'blue'},{key:'cuti-izin',label:'Cuti/Izin',class:'orange'},{key:'koreksi',label:'Koreksi',class:'cyan'},{key:'lembur',label:'Lembur',class:'purple'}];const filtered=computed(()=>active.value==='all'?props.items:props.items.filter(x=>x.type===active.value));const detail=x=>x.type==='cuti-izin'?`${x.kategori||'-'} — ${x.jenis||'-'} · ${x.jumlah_hari||0} hari`:x.type==='koreksi'?`${x.jenis_koreksi||'-'}${x.jam_koreksi?' · '+x.jam_koreksi:''}`:`${x.jam_mulai||'-'} - ${x.jam_selesai||'-'} · ${Number(x.total_jam||0).toFixed(2)} jam`;</script>
<style scoped>.attendance-pwa{padding:2px 0 84px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:7px}.stats button{padding:8px;border:1px solid #e5e7eb;border-radius:11px;background:#fff;text-align:left}.stats span{display:block;color:#64748b;font-size:8.75px;font-weight:800}.stats strong{display:block;margin-top:2px;color:#111827;font-size:21.25px}.stats .blue{border-top:3px solid #2563eb}.stats .orange{border-top:3px solid #f59e0b}.stats .cyan{border-top:3px solid #06b6d4}.stats .purple{border-top:3px solid #7c3aed}.filter-row{display:flex;gap:5px;overflow-x:auto;padding-bottom:7px}.filter-row button{border:1px solid #e5e7eb;border-radius:999px;background:#fff;padding:5px 8px;color:#475569;font-size:10px;font-weight:900;white-space:nowrap}.filter-row button.active{background:#0f172a;color:#fff}.card{padding:10px;background:#fff;border:1px solid #e5e7eb;border-radius:15px}.title{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px}.title h6{margin:0;color:#111827;font-size:15px;font-weight:950}.title span{color:#64748b;font-size:10px}.icon-btn{width:30px;height:30px;border:1px solid #e5e7eb;border-radius:9px;background:#fff;color:#2563eb}.list{display:flex;flex-direction:column;gap:6px}.item{padding:8px;border:1px solid #eef2f7;border-left:3px solid #f59e0b;border-radius:11px}.top{display:flex;justify-content:space-between;gap:6px}.top strong{display:block;font-size:12.5px;color:#111827}.top small{display:block;color:#64748b;font-size:9.38px;margin-top:2px}.status{padding:3px 5px;border-radius:999px;font-size:8.75px;font-weight:900}.pending{background:#fef3c7;color:#92400e}.mini{padding-top:5px;margin-top:5px;border-top:1px solid #f1f5f9}.mini span{display:block;color:#94a3b8;font-size:8.75px;font-weight:800}.mini strong{display:block;margin-top:2px;color:#334155;font-size:10.62px;line-height:1.3}.attachment{display:inline-block;margin-top:6px;color:#2563eb;text-decoration:none;font-size:10px;font-weight:900}.actions{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:7px}.actions button{height:28px;border:0;border-radius:8px;background:#dcfce7;color:#166534;font-size:10.62px;font-weight:900}.actions button:last-child{background:#fee2e2;color:#991b1b}.empty{text-align:center;padding:22px;color:#64748b;font-size:11.25px}@media(max-width:520px){.stats{grid-template-columns:repeat(2,1fr)}}</style>